@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,500;1,600&display=swap');
:root{color-scheme:dark;--cream:#ece8d8;--muted:#a19f90;--gold:#e5b969;--green:#9fbc9d;--ink:#101513}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);font-family:'DM Sans',sans-serif;color:var(--cream);touch-action:none}button{font:inherit}#game{position:relative;width:100%;height:100dvh;overflow:hidden;background:#101513}#view{display:block;width:100%;height:100%;image-rendering:auto;touch-action:none}.grain{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.87' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");mix-blend-mode:screen;animation:grain .2s steps(2) infinite}@keyframes grain{0%{transform:translate(0)}50%{transform:translate(1%,-1%)}100%{transform:translate(-1%,1%)}}.vignette{position:absolute;inset:0;z-index:3;pointer-events:none;background:radial-gradient(ellipse at center,transparent 36%,rgba(5,9,8,.35) 100%);box-shadow:inset 0 0 100px #080c0bb0}.topbar{position:absolute;z-index:5;left:0;right:0;top:0;padding:24px 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(#0b100fba,transparent);pointer-events:none}.brand{display:flex;gap:10px;align-items:center;font-size:10px;line-height:1.15;letter-spacing:1.6px;font-weight:700;color:#e8e4d6}.brand-mark{color:var(--gold);font-size:23px}.brand small{font-size:7px;letter-spacing:1.4px;color:#a8aa9d}.night-status{text-align:center;font:10px 'DM Mono',monospace;letter-spacing:1px;color:#eee9d9}.night-status small{display:block;margin-top:5px;font-size:8px;color:#a0a297;letter-spacing:1.7px}.live-dot,.dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c9a276;margin:0 7px 1px 0;box-shadow:0 0 10px #dca35a}.icon-btn{pointer-events:auto;background:#18201dcc;border:1px solid #ffffff24;color:var(--cream);border-radius:50%;width:36px;height:36px;font-size:15px}.hud{position:absolute;z-index:5;top:91px;left:34px;right:34px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.hud[hidden],.screen[hidden],.letterbox[hidden],.map-panel[hidden],.touch-controls[hidden],.reticle[hidden],.interact-hint[hidden],.message[hidden]{display:none}.objective-card{width:240px;padding:14px 16px 12px;background:#111917cb;border:1px solid #e8dfc11a;backdrop-filter:blur(8px)}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.8px;color:#c7ae7b}.objective-card>div:nth-child(2){font-size:13px;margin:6px 0 12px;color:#e6e2d5}.progress{height:2px;background:#42483e}.progress span{display:block;width:0;height:100%;background:var(--gold);transition:width .5s}.progress-label{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#999b8b;margin-top:7px}.status-pills{display:flex;gap:7px}.pill{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#c6c7b9;background:#111917bd;border:1px solid #e8dfc11a;padding:8px 10px}.pill span:first-child{color:#d9bd7a;margin-right:6px}.pulse-icon{font-size:11px}.reticle{position:absolute;z-index:5;left:50%;top:50%;width:15px;height:15px;transform:translate(-50%,-50%);opacity:.73}.reticle i,.reticle b{position:absolute;background:#efe9d8;left:7px;top:0;width:1px;height:15px}.reticle b{transform:rotate(90deg)}.interact-hint{position:absolute;z-index:6;left:50%;top:calc(50% + 24px);transform:translateX(-50%);font:9px 'DM Mono',monospace;letter-spacing:1.7px;padding:8px 11px;background:#111917d9;border:1px solid #ffffff28;color:#e9e3d3;white-space:nowrap;align-items:center;gap:8px}.interact-hint:not([hidden]){display:flex}.keycap{border:1px solid #b8b39c;padding:3px 6px;color:var(--gold)}.message{position:absolute;z-index:6;top:26%;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:1.7px;color:#efe9d8;background:#111917d9;border:1px solid #ffffff24;padding:10px 15px;white-space:nowrap}.letterbox{position:absolute;z-index:8;inset:0;background:#090e0dd9;display:grid;place-items:center;backdrop-filter:blur(5px)}.letter-inner{max-width:480px;padding:30px;text-align:center}.letter-text{font:22px/1.48 'Playfair Display',serif;color:#e9e4d6;margin:20px auto 28px}.letter-inner button{border:0;background:none;color:var(--gold);font:10px 'DM Mono',monospace;letter-spacing:1.5px;padding:10px;cursor:pointer}.letter-inner button span,.primary-btn span{margin-left:18px}.map-panel{position:absolute;z-index:5;right:30px;bottom:26px;padding:10px;background:#101715cf;border:1px solid #e8dfc126;pointer-events:none}.map-heading{font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:#bebbaa;display:flex;justify-content:space-between;margin:0 2px 6px}.map-heading span{color:var(--gold)}#minimap{width:124px;height:124px;display:block;background:#16201a}.map-legend{font:7px 'DM Mono',monospace;letter-spacing:.8px;color:#999b8b;margin-top:5px}.map-legend i{display:inline-block;background:#d3d4b8;width:5px;height:5px;border-radius:50%;margin-right:4px}.map-legend b{color:#e2bf79;margin-left:10px}.screen{position:absolute;z-index:7;inset:0;display:flex;align-items:center;padding:80px 10vw;background:linear-gradient(90deg,#0c1211f2 0%,#101715e8 43%,#0d1311a6 67%,#0d13117a 100%)}.title-copy{width:58%;max-width:650px}.title-copy>.eyebrow{margin-bottom:20px}.title-copy h1{font:600 clamp(45px,6.1vw,82px)/.93 'Playfair Display',serif;letter-spacing:-2.6px;margin:0;color:#f0ecdf}.title-copy h1 em{font-size:.77em;font-weight:500;letter-spacing:-1.4px;color:#d9c99f}.dek{margin:23px 0 20px;color:#c4c5b9;font-size:14px;line-height:1.8}.title-rule{width:55px;height:1px;background:#b89a64;margin:22px 0}.story-note{display:flex;gap:13px;align-items:flex-start;max-width:420px;color:#c2c2b5}.story-note span{color:var(--gold);font-size:19px}.story-note p{font-size:12px;line-height:1.65;margin:0}.primary-btn{cursor:pointer;border:1px solid #d5b875;background:#d7b772;color:#171912;padding:15px 20px;margin-top:27px;font:10px 'DM Mono',monospace;letter-spacing:1.4px;transition:background .2s,transform .2s}.primary-btn:hover{background:#efd494;transform:translateY(-2px)}.primary-btn span{font-size:14px}.control-note,.mobile-note{margin-top:19px;color:#979a8d;font:8px 'DM Mono',monospace;letter-spacing:.9px}.control-note span{color:#d6d3c4}.control-note i{color:#9e8050;font-style:normal;padding:0 6px}.mobile-note{display:none}.save-note{font:9px 'DM Mono',monospace;color:#a3b59b;margin-top:12px;letter-spacing:1px}.title-side{position:absolute;right:9vw;top:50%;transform:translateY(-50%);width:min(27vw,310px)}.postcard{border:1px solid #d6c69a66;padding:8px;background:#161c18;transform:rotate(2deg);box-shadow:0 18px 65px #0008}.postcard-scene{height:195px;overflow:hidden;position:relative;background:linear-gradient(#35454a 0%,#606662 52%,#202c28 53%,#121a17 100%)}.moon{position:absolute;right:18%;top:16%;width:30px;height:30px;background:#e6d6a5;border-radius:50%;box-shadow:0 0 25px #e6d6a566}.p-houses{position:absolute;bottom:36px;width:100%;display:flex;justify-content:space-around;align-items:end}.p-houses i{display:block;position:relative;background:#27312b;width:55px;height:74px;border-top:18px solid #374238}.p-houses i:nth-child(2){height:96px;width:70px;background:#3c4035;border-top-color:#55483a}.p-houses i:after{content:'';position:absolute;left:14px;top:26px;width:10px;height:15px;background:#dfb46b;box-shadow:20px 2px 0 #cab07866}.p-road{position:absolute;bottom:0;left:0;width:100%;height:38px;background:#212722;clip-path:polygon(35% 0,68% 0,100% 100%,0 100%)}.p-road:after{content:'';position:absolute;left:50%;height:100%;border-left:1px dashed #c9b57a}.p-lamp{position:absolute;bottom:29px;left:22%;height:91px;width:2px;background:#17201b}.p-lamp:before{content:'';position:absolute;left:-4px;top:-2px;width:10px;height:3px;background:#e5c27b;box-shadow:0 0 21px 8px #dbbb7555}.postcard-caption{display:flex;justify-content:space-between;padding:10px 3px 3px;color:#c7bc97;font:8px 'DM Mono',monospace;letter-spacing:1.2px}.side-quote{font:italic 16px/1.6 'Playfair Display',serif;color:#d9d4c6;margin-top:30px;text-align:right}.side-quote small{display:block;margin-top:7px;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#a8a796}.ending{flex-direction:column;justify-content:center;text-align:center;background:#101715eF}.ending h2{font:500 clamp(38px,6vw,65px) 'Playfair Display',serif;margin:20px 0 8px}.ending p{color:#c1c2b5;font-size:14px}.ending-stats{margin-top:18px;color:#a6b69b;font:9px 'DM Mono',monospace;letter-spacing:1.3px}.touch-controls{position:absolute;z-index:6;left:0;right:0;bottom:0;height:180px;pointer-events:none}.stick-zone{position:absolute;pointer-events:auto;left:20px;bottom:20px;width:126px;height:126px;display:grid;place-items:center;touch-action:none}.stick-base{width:108px;height:108px;border:1px solid #e8e0cb55;background:#111a17a3;border-radius:50%;display:grid;place-items:center;box-shadow:inset 0 0 22px #0008}.stick-knob{width:44px;height:44px;border-radius:50%;background:#d8c99c99;border:1px solid #fff9;box-shadow:0 2px 8px #0008;transform:translate(0,0)}.touch-action{pointer-events:auto;position:absolute;right:24px;bottom:36px;width:59px;height:59px;border-radius:50%;background:#151d19c9;border:1px solid #e4d6ae77;color:#e6dcbf;font:8px 'DM Mono',monospace;letter-spacing:1px;touch-action:none}.interact-touch{right:90px;bottom:83px;width:48px;height:48px}.touch-controls:not([hidden]){display:block}
@media(max-width:700px){.topbar{padding:14px 17px}.brand{font-size:9px}.brand small{font-size:6px}.brand-mark{font-size:19px}.night-status{font-size:9px}.night-status small{font-size:7px}.icon-btn{width:31px;height:31px}.screen{padding:98px 25px 35px;background:linear-gradient(90deg,#0c1211ed,#101715c9 72%,#10171599);align-items:flex-start;overflow:auto}.title-copy{width:100%;padding-top:7vh}.title-copy>.eyebrow{font-size:8px;margin-bottom:16px}.title-copy h1{font-size:clamp(43px,12vw,67px);letter-spacing:-1.8px}.title-copy h1 em{font-size:.72em}.dek{font-size:12px;line-height:1.7;margin:17px 0}.story-note p{font-size:11px}.title-rule{margin:16px 0}.title-side{right:24px;top:auto;bottom:25px;transform:none;width:110px;opacity:.58}.postcard-scene{height:70px}.moon{width:15px;height:15px}.p-houses{bottom:17px}.p-houses i{width:19px;height:31px;border-top-width:7px}.p-houses i:nth-child(2){width:23px;height:39px;border-top-width:7px}.p-houses i:after{left:5px;top:9px;width:4px;height:7px;box-shadow:8px 1px 0 #cab07866}.p-road{height:18px}.p-lamp{bottom:14px;height:35px}.postcard-caption{font-size:5px;padding:6px 2px 2px}.side-quote{display:none}.primary-btn{margin-top:20px;padding:14px 16px}.control-note{display:none}.mobile-note{display:block;font-size:7px}.save-note{font-size:8px}.hud{top:67px;left:14px;right:14px}.objective-card{width:min(220px,61vw);padding:10px 11px}.objective-card>div:nth-child(2){font-size:11px;margin:4px 0 9px}.eyebrow{font-size:8px}.progress-label{font-size:7px}.status-pills{flex-direction:column;gap:5px}.pill{font-size:7px;padding:6px 7px}.map-panel{right:12px;bottom:12px;padding:7px}.map-heading{font-size:7px}#minimap{width:90px;height:90px}.map-legend{font-size:6px}.letter-text{font-size:19px}.letter-inner{padding:26px}.ending h2{font-size:41px}.message{top:29%;font-size:8px}.interact-hint{top:calc(50% + 19px);font-size:8px}.touch-controls{height:160px}.stick-zone{left:12px;bottom:13px}.touch-action{right:15px;bottom:25px}.interact-touch{right:77px;bottom:69px}}
@media(max-height:650px) and (min-width:701px){.screen{padding-top:55px;padding-bottom:30px}.title-copy>.eyebrow{margin-bottom:12px}.title-copy h1{font-size:56px}.dek{margin:14px 0}.title-rule{margin:14px 0}.primary-btn{margin-top:17px}.title-side{width:240px}.postcard-scene{height:140px}}

(() => {
  'use strict';
  const canvas = document.getElementById('view');
  const ctx = canvas.getContext('2d', { alpha: false });
  const $ = (id) => document.getElementById(id);
  const ui = { title:$('titleScreen'), ending:$('endingScreen'), hud:$('hud'), touch:$('touchControls'), reticle:$('reticle'), hint:$('interactHint'), hintText:$('hintText'), map:$('mapPanel'), minimap:$('minimap'), message:$('message'), letter:$('letterbox'), letterText:$('letterText'), letterEyebrow:$('letterEyebrow'), progress:$('progressFill'), progressLabel:$('progressLabel'), objective:$('objective'), nerve:$('nerveLabel'), save:$('saveLabel'), clock:$('clock') };
  const W=25,H=25, world=Array.from({length:H},()=>Array(W).fill(1));
  const avenues=[2,3,8,9,14,15,20,21];
  for(let y=1;y<H-1;y++) for(let x=1;x<W-1;x++) if(avenues.includes(x)||avenues.includes(y)) world[y][x]=0;
  const tile=(x,y)=>world[Math.floor(y)]?.[Math.floor(x)] ?? 1;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const memories=[
    {x:8.5,y:2.55,title:'The blue scarf',type:'A NOTE FROM MRS. ALVAREZ',text:'“I saw a blue scarf by the bus stop. I remember because I was carrying the lemon cake, and the rain had just started. It was still warm from the oven.”\n\nMrs. Alvarez leaves a porch light on for you.'},
    {x:14.5,y:8.55,title:'The porch light',type:'A PAGE FROM YOUR JOURNAL',text:'You wrote this weeks ago: “Mr. Bell fixed the porch light on number 14. He said it was flickering before the storm. He was wearing his gardening gloves.”\n\nThe handwriting is yours. The date is not.'},
    {x:20.5,y:14.5,title:'A familiar voice',type:'A VOICEMAIL, 11:38 PM',text:'“Hey, it’s June. I’m home safe. Don’t wait up. You know how the street sounds after rain—it makes every footstep seem like two.”\n\nJune is your sister. She lives three doors down.'}
  ];
  const exit={x:20.5,y:20.5};
  const saveKey='marigold-night-save-v1';
  let saved={found:[],ended:false,visits:0};
  try { const raw=JSON.parse(localStorage.getItem(saveKey)||'{}'); if(Array.isArray(raw.found))saved=Object.assign(saved,raw); } catch(_){}
  let active=false,paused=true,over=false,player={x:2.5,y:2.5,a:0}, killer={x:20.5,y:2.5,a:0}, time=0,last=0,frame=0,stress=0,battery=1,flashlight=true, messageTimer=0, invuln=0, finishTime=0;
  let keys={},mouseDown=false,dragLook=false,lastTouchX=0,moveInput={x:0,y:0},audio=null,soundOn=true;
  let cw=480,ch=270,zbuffer=new Float32Array(cw),sprites=[];
  const fov=Math.PI/3, tanHalf=Math.tan(fov/2);
  const lampPositions=[{x:2.5,y:8.5},{x:8.5,y:2.5},{x:14.5,y:2.5},{x:20.5,y:8.5},{x:8.5,y:14.5},{x:14.5,y:20.5},{x:20.5,y:20.5},{x:2.5,y:20.5},{x:8.5,y:8.5},{x:14.5,y:14.5}];
  const neighbors=[{x:3.3,y:7.45,name:'MRS. ALVAREZ',phase:0},{x:8.45,y:15.7,name:'MR. BELL',phase:2.1},{x:15.6,y:8.55,name:'JUNE',phase:4.2},{x:20.55,y:3.3,name:'THE POSTMAN',phase:1.4}];
  function persist(){localStorage.setItem(saveKey,JSON.stringify(saved));ui.save.textContent='SAVED';}
  function setMessage(text,duration=2.5){ui.message.textContent=text;ui.message.hidden=false;messageTimer=duration;}
  function seeded(x,y){const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n);}
  function resize(){const dpr=Math.min(window.devicePixelRatio||1,1.5);cw=Math.max(300,Math.min(700,Math.floor(innerWidth*dpr)));ch=Math.max(200,Math.floor(cw*innerHeight/innerWidth));canvas.width=cw;canvas.height=ch;canvas.style.width='100%';canvas.style.height='100%';zbuffer=new Float32Array(cw);}
  window.addEventListener('resize',resize); resize();
  function start(){active=true;paused=false;over=false;ui.title.hidden=true;ui.ending.hidden=true;ui.hud.hidden=false;ui.reticle.hidden=false;ui.map.hidden=false;ui.touch.hidden=false;player={x:2.5,y:2.5,a:0};killer={x:20.5,y:2.5,a:Math.PI};stress=0;finishTime=performance.now();saved.visits=(saved.visits||0)+1;persist();initAudio();setMessage('The rain is letting up. Your mailbox is still open.',4);}
  $('startBtn').addEventListener('click',start);
  $('returnBtn').addEventListener('click',()=>{ui.ending.hidden=true;ui.title.hidden=false;active=false;paused=true;ui.hud.hidden=true;ui.touch.hidden=true;ui.map.hidden=true;ui.reticle.hidden=true;});
  $('letterContinue').addEventListener('click',()=>{ui.letter.hidden=true;paused=false;});
  $('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').textContent=soundOn?'♫':'×';if(audio)audio.master.gain.setTargetAtTime(soundOn?.14:0,audio.ctx.currentTime,.12);});
  function initAudio(){if(audio){audio.ctx.resume();return;}try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ac=new AC(),master=ac.createGain();master.gain.value=soundOn?.14:0;master.connect(ac.destination);const osc=ac.createOscillator(),gain=ac.createGain(),filter=ac.createBiquadFilter();osc.type='triangle';osc.frequency.value=54;filter.type='lowpass';filter.frequency.value=140;gain.gain.value=.32;osc.connect(filter);filter.connect(gain);gain.connect(master);osc.start();const buffer=ac.createBuffer(1,ac.sampleRate*2,ac.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.12;const noise=ac.createBufferSource(),ng=ac.createGain(),nf=ac.createBiquadFilter();noise.buffer=buffer;noise.loop=true;nf.type='lowpass';nf.frequency.value=850;ng.gain.value=.2;noise.connect(nf);nf.connect(ng);ng.connect(master);noise.start();audio={ctx:ac,master,osc,gain};}catch(_){}}
  function tone(freq=220,dur=.15){if(!audio||!soundOn)return;const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+dur);o.connect(g);g.connect(audio.master);o.start();o.stop(audio.ctx.currentTime+dur);}

