function tone(freq=220,dur=.15){if(!audio||!soundOn)return;const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+dur);o.connect(g);g.connect(audio.master);o.start();o.stop(audio.ctx.currentTime+dur);}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(!active||paused||e.repeat)return;if(e.code==='KeyE'||e.code==='Space')interact();if(e.code==='KeyQ')toggleFlashlight();if(e.code==='KeyM')ui.map.hidden=!ui.map.hidden;});
window.addEventListener('keyup',e=>{keys[e.code]=false;});
canvas.addEventListener('click',()=>{if(active&&document.pointerLockElement!==canvas&&innerWidth>700)canvas.requestPointerLock?.();});
document.addEventListener('mousemove',e=>{if(active&&!paused&&document.pointerLockElement===canvas)player.a+=e.movementX*.0022;});
canvas.addEventListener('pointerdown',e=>{if(innerWidth<=700&&active&&!paused){dragLook=true;lastTouchX=e.clientX;canvas.setPointerCapture?.(e.pointerId);}});
canvas.addEventListener('pointermove',e=>{if(dragLook&&active&&!paused){player.a+=(e.clientX-lastTouchX)*.006;lastTouchX=e.clientX;}});
canvas.addEventListener('pointerup',()=>dragLook=false);canvas.addEventListener('pointercancel',()=>dragLook=false);
const stickZone=$('stickZone'),stickKnob=$('stickKnob');let stickPointer=null,stickOrigin={x:0,y:0};
stickZone.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;const r=stickZone.getBoundingClientRect();stickOrigin={x:r.left+r.width/2,y:r.top+r.height/2};stickZone.setPointerCapture(e.pointerId);updateStick(e);});
stickZone.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)updateStick(e);});
function updateStick(e){const dx=e.clientX-stickOrigin.x,dy=e.clientY-stickOrigin.y,len=Math.hypot(dx,dy),s=Math.min(1,len/42),x=len?dx/len*s:0,y=len?dy/len*s:0;moveInput={x,y};stickKnob.style.transform=`translate(${x*28}px,${y*28}px)`;}
function releaseStick(e){if(e.pointerId===stickPointer){stickPointer=null;moveInput={x:0,y:0};stickKnob.style.transform='translate(0,0)';}}
stickZone.addEventListener('pointerup',releaseStick);stickZone.addEventListener('pointercancel',releaseStick);
$('touchInteract').addEventListener('pointerdown',e=>{e.preventDefault();interact();});
